import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Subscription } from 'rxjs';
import { NotificationService, Notification } from '../../services/notification.service';
import { trigger, state, style, transition, animate } from '@angular/animations';

@Component({
  selector: 'app-notification',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div class="notification-container">
      <div 
        *ngFor="let notification of notifications; trackBy: trackByNotification" 
        class="notification"
        [ngClass]="notification.type">
        <div style="color: red; font-weight: bold;">DEBUG: {{ notification.message }}</div>
      </div>
    </div>
  `,
  styles: [`
    .notification-container {
      position: fixed;
      top: 20px;
      right: 20px;
      z-index: 9999;
      max-width: 400px;
      min-width: 300px;
    }

    .notification {
      background: white;
      border-radius: 12px;
      box-shadow: 0 8px 25px rgba(0,0,0,0.15);
      margin-bottom: 15px;
      padding: 20px 25px;
      border-left: 6px solid;
      font-size: 16px;
      color: #333;
      font-weight: 500;
      line-height: 1.4;
      min-height: 60px;
      display: flex;
      align-items: center;
      word-wrap: break-word;
      transition: all 0.3s ease;
    }

    .notification:hover {
      transform: translateY(-2px);
      box-shadow: 0 12px 35px rgba(0,0,0,0.2);
    }

    .notification.success {
      border-left-color: #28a745;
      background: linear-gradient(135deg, #d4edda 0%, #ffffff 100%);
      color: #155724;
    }

    .notification.error {
      border-left-color: #dc3545;
      background: linear-gradient(135deg, #f8d7da 0%, #ffffff 100%);
      color: #721c24;
    }

    .notification.warning {
      border-left-color: #ffc107;
      background: linear-gradient(135deg, #fff3cd 0%, #ffffff 100%);
      color: #856404;
    }

    .notification.info {
      border-left-color: #17a2b8;
      background: linear-gradient(135deg, #d1ecf1 0%, #ffffff 100%);
      color: #0c5460;
    }

    .notification.fade-out {
      opacity: 0;
      transform: translateX(100%);
      transition: all 0.3s ease-in;
    }

    .notification-content {
      display: flex;
      align-items: center;
      width: 100%;
      gap: 15px;
    }

    .notification-icon {
      font-size: 20px;
      font-weight: bold;
      min-width: 24px;
      text-align: center;
    }

    .notification-message {
      flex: 1;
      font-size: 16px;
      line-height: 1.4;
      color: inherit;
      word-break: break-word;
      white-space: normal;
    }
  `],
  animations: [
    trigger('slideInOut', [
      state('in', style({
        transform: 'translateX(0)',
        opacity: 1
      })),
      state('out', style({
        transform: 'translateX(100%)',
        opacity: 0
      })),
      transition('in => out', [
        animate('300ms ease-in')
      ]),
      transition('void => in', [
        style({ transform: 'translateX(100%)', opacity: 0 }),
        animate('300ms ease-out')
      ])
    ])
  ]
})
export class NotificationComponent implements OnInit, OnDestroy {
  notifications: Notification[] = [];
  private subscription: Subscription = new Subscription();

  constructor(private notificationService: NotificationService) {}

  ngOnInit() {
    this.subscription = this.notificationService.getNotifications().subscribe(notification => {
      this.notifications.push(notification);

      setTimeout(() => {
        this.removeNotification(notification.id);
      }, notification.duration || 5000);
    });
  }

  ngOnDestroy() {
    this.subscription.unsubscribe();
  }

  removeNotification(id: number) {
    const notification = this.notifications.find(n => n.id === id);
    if (notification) {
      notification['fade-out'] = true;
      setTimeout(() => {
        this.notifications = this.notifications.filter(n => n.id !== id);
      }, 300);
    }
  }

  onAnimationDone(event: any, notification: Notification) {
    // Lógica adicional se necessário
  }

  trackByNotification(index: number, notification: Notification): number {
    return notification.id;
  }
}
